const { Library } = require('./s1_library.js');

// Test the new methods
const library = new Library();

// Add some books
library.addBook("978-0-123456-78-9", "The Great Gatsby", 3);
library.addBook("978-0-987654-32-1", "1984", 2);

console.log("Testing returnBook and loans methods...");

// Test loans with no books
console.log("Loans for Alice (should be empty):", library.loans("Alice"));

// Checkout a book
library.checkout("978-0-123456-78-9", "Alice");
console.log("Loans for Alice (should have one book):", library.loans("Alice"));

// Test returnBook with valid return
library.returnBook("978-0-123456-78-9", "Alice");
console.log("Loans for Alice (should be empty after return):", library.loans("Alice"));

// Test returnBook with invalid return (member doesn't have the book)
try {
    library.returnBook("978-0-123456-78-9", "Bob");
    console.log("ERROR: Should have thrown an error!");
} catch (e) {
    console.log("Correctly threw error for member without book:", e.message);
}

// Test loans with multiple books
library.checkout("978-0-123456-78-9", "Charlie");
library.checkout("978-0-987654-32-1", "Charlie");
console.log("Loans for Charlie (should have two books):", library.loans("Charlie"));

// Test returnBook with multiple copies
library.checkout("978-0-123456-78-9", "Charlie"); // Checkout again
console.log("Loans for Charlie (should have three books now):", library.loans("Charlie"));

// Return one copy
library.returnBook("978-0-123456-78-9", "Charlie");
console.log("Loans for Charlie (should have two books after returning one):", library.loans("Charlie"));

console.log("All tests completed successfully!");

